'use strict';
const test=require('node:test'),assert=require('node:assert/strict');const Bootstrap=require('../recorder/files/bootstrap').Bootstrap;
function fake(){let uid=null,starts=[],stops=[],states=[],config=null,probes=0;const deps={findApp:()=>uid==null?null:{uid,version:'0.2.4'},platform:()=>{},ensureTLS:async()=>({key:'/private/key',cert:'/private/cert'}),readHardware:()=>config,saveHardware:async x=>{config=x;},probe:()=>{probes++;return Promise.resolve({streams:2,packets:8});},receiverHash:'abc',prepare:async()=>{},legacyEnrollment:()=>null,retireLegacy:async()=>{},publish:async(a,state)=>{states.push([a&&a.uid,state]);},start:async a=>{starts.push(a.uid);return {stop:async()=>{stops.push(a.uid);}};}};return {deps,uid:x=>{uid=x;},starts,stops,states,config:()=>config,probes:()=>probes};}
test('waits for dependency app, provisions UID and credentials, stops when app is removed',async()=>{const f=fake(),b=new Bootstrap(f.deps);await b.tick();assert.deepEqual(f.starts,[]);f.uid(12341);await b.tick();assert.deepEqual(f.starts,[12341]);assert.equal(f.config().uid,12341);assert.equal(f.config().adapterVerified,true);assert.equal(f.probes(),1);await b.tick();assert.equal(f.starts.length,1);f.uid(null);await b.tick();assert.deepEqual(f.stops,[12341]);await b.stop();});
test('UID changes stop old recorder before starting new UID and retain camera verification',async()=>{const f=fake(),b=new Bootstrap(f.deps);f.uid(12341);await b.tick();f.uid(12342);await b.tick();assert.deepEqual(f.stops,[12341]);assert.deepEqual(f.starts,[12341,12342]);assert.equal(f.config().uid,12342);assert.equal(f.probes(),1);await b.stop();assert.deepEqual(f.stops,[12341,12342]);});
test('failed or missing camera never sets verified flags or starts recorder',async()=>{const f=fake();f.uid(12341);f.deps.probe=()=>Promise.reject(Error('Waiting for supported camera streams'));const b=new Bootstrap(f.deps);await assert.rejects(b.tick(),/camera/);assert.equal(f.config(),null);assert.deepEqual(f.starts,[]);await b.stop();});
test('shutdown cancels probe and cannot start recording after late completion',async()=>{const f=fake();f.uid(12341);let resolve,cancelled=false;const p=new Promise(r=>{resolve=r;});p.cancel=()=>{cancelled=true;resolve({streams:2});};f.deps.probe=()=>p;const b=new Bootstrap(f.deps),tick=b.tick();await new Promise(r=>setImmediate(r));await b.stop();await tick;assert.equal(cancelled,true);assert.deepEqual(f.starts,[]);});
test('app removal during probe discards the result instead of enrolling stale UID',async()=>{const f=fake();f.uid(12341);f.deps.probe=async()=>{f.uid(null);return {streams:2};};const b=new Bootstrap(f.deps);await b.tick();assert.equal(f.config(),null);assert.deepEqual(f.starts,[]);await b.stop();});

test('production bootstrap can prepare the recorder control directory through the exported runtime contract',async t=>{
 const fs=require('fs'),os=require('os'),path=require('path'),main=require('../recorder/files/main');
 const root=fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()),'bv-controls-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));
 const directory=path.join(root,'control');await main.prepareControls(directory,process.getuid());assert.equal(fs.statSync(directory).mode&511,448);assert.equal(fs.statSync(directory).uid,process.getuid());
});
test('first-time native camera probe starts control and releases it on success or failure',async()=>{const {probeWithCameraControl}=require('../recorder/files/bootstrap');const order=[];const controller={start:async()=>{order.push('start');},close:async()=>{order.push('close');}};const result=await probeWithCameraControl(controller,()=>{order.push('probe');return Promise.resolve({streams:1});});assert.deepEqual(result,{streams:1});assert.deepEqual(order,['start','probe','close']);await assert.rejects(probeWithCameraControl(controller,()=>Promise.reject(Error('no cameras'))),/no cameras/);assert.equal(order.at(-1),'close');});
test('cancelling setup releases camera control and cancels the hardware probe',async()=>{const {probeWithCameraControl}=require('../recorder/files/bootstrap');let cancelled=false,closed=0,reject;const p=new Promise((a,b)=>reject=b);p.cancel=()=>{cancelled=true;reject(Error('cancelled'));};const task=probeWithCameraControl({start:async()=>{},close:async()=>{closed++;}},()=>p);await new Promise(r=>setImmediate(r));task.cancel();await assert.rejects(task,/cancelled/);assert.equal(cancelled,true);assert.ok(closed>=1);});
